            "script": "\n[ABERTURA - 5s]\nLogotipo da Coffee Express com efeito din\u00e2mico.\n\n[NARRA\u00c7\u00c3O - 10s]\n\"Voc\u00ea j\u00e1 sonhou em ter seu pr\u00f3prio neg\u00f3cio, mas tem medo dos riscos? A franquia Coffee Express pode ser a resposta que voc\u00ea procura.\"\n\n[CENA 1 - 10s]\nMostrar franqueados bem-sucedidos em suas unidades, sorridentes e atendendo clientes.\n\"Mais de 172 empreendedores j\u00e1 transformaram suas vidas com a Coffee Express.\"\n\n[CENA 2 - 10s]\nGr\u00e1ficos animados mostrando crescimento do setor e ROI.\n\"O mercado de Servi\u00e7os cresce 10% ao ano, e nossos franqueados t\u00eam ROI m\u00e9dio de 25%.\"\n\n[CENA 3 - 10s]\nImagens do treinamento e suporte oferecidos.\n\"Oferecemos suporte completo, desde a escolha do ponto at\u00e9 a inaugura\u00e7\u00e3o e opera\u00e7\u00e3o di\u00e1ria.\"\n\n[CENA 4 - 10s]\nDepoimento r\u00e1pido de um franqueado de sucesso.\n\"A Coffee Express mudou minha vida. Hoje tenho liberdade financeira e tempo para minha fam\u00edlia.\"\n\n[FECHAMENTO - 5s]\n\"Investimento a partir de R$ 100,000,00. Transforme seu futuro com a franquia Coffee Express.\"\n[MOSTRAR SITE E CTA]\n                ",
