            "script": "\n[ABERTURA - 3s]\nLogo da Coffee Express com slogan.\n\n[NARRA\u00c7\u00c3O - 5s]\n\"O mercado de Servi\u00e7os est\u00e1 em expans\u00e3o. Voc\u00ea est\u00e1 pronto para aproveitar essa oportunidade?\"\n\n[CENA 1 - 7s]\nMostrar unidades da franquia em opera\u00e7\u00e3o, clientes satisfeitos.\n\"A Coffee Express \u00e9 l\u00edder no segmento, com modelo de neg\u00f3cio validado e suporte completo.\"\n\n[CENA 2 - 7s]\nMostrar n\u00fameros de crescimento e resultados.\n\"Investimento a partir de R$ 100,000,00, com retorno em apenas 36 meses.\"\n\n[CENA 3 - 5s]\nMostrar equipe de suporte e treinamento.\n\"Voc\u00ea n\u00e3o estar\u00e1 sozinho. Nossa equipe te acompanha em cada passo.\"\n\n[FECHAMENTO - 3s]\n\"Seja parte do sucesso. Coffee Express - seu futuro come\u00e7a aqui.\"\n[MOSTRAR SITE E TELEFONE]\n                ",
