            "script": "\n[ABERTURA - 5s]\nMostrar logotipo da Beauty Spot e t\u00edtulo \"Hist\u00f3rias de Sucesso\"\n\n[INTRODU\u00c7\u00c3O - 10s]\nNarrador: \"Conhe\u00e7a a hist\u00f3ria de Jo\u00e3o Silva, franqueado da Beauty Spot h\u00e1 2 anos. Ele deixou o emprego corporativo para empreender e hoje comanda uma das unidades mais lucrativas da rede.\"\n\n[DEPOIMENTO PARTE 1 - 20s]\nJo\u00e3o: \"Sempre sonhei em ter meu pr\u00f3prio neg\u00f3cio, mas tinha medo dos riscos. Quando conheci a Beauty Spot, vi que era poss\u00edvel empreender com seguran\u00e7a. O modelo de neg\u00f3cio j\u00e1 estava validado e o suporte da franqueadora me deu confian\u00e7a.\"\n\n[CENAS DA UNIDADE - 15s]\nMostrar a unidade em funcionamento, clientes satisfeitos, Jo\u00e3o interagindo com sua equipe.\nNarrador: \"A unidade de Jo\u00e3o atingiu o ponto de equil\u00edbrio em X meses e hoje fatura Y% acima da m\u00e9dia da rede.\"\n\n[DEPOIMENTO PARTE 2 - 20s]\nJo\u00e3o: \"O que mais me surpreendeu foi o suporte constante. Desde a escolha do ponto at\u00e9 o treinamento da equipe, a franqueadora esteve presente em cada etapa. Hoje tenho qualidade de vida e seguran\u00e7a financeira que nunca tive como funcion\u00e1rio.\"\n\n[FECHAMENTO - 20s]\nJo\u00e3o: \"Se voc\u00ea est\u00e1 pensando em empreender, considere a Beauty Spot. Foi a melhor decis\u00e3o que tomei.\"\nNarrador: \"Seja como Jo\u00e3o e tantos outros empreendedores de sucesso. Invista na franquia Beauty Spot e transforme seu futuro.\"\n[MOSTRAR SITE E TELEFONE]\n            ",
