// Atualizar timestamp de última atualização
document.getElementById('last-update-time').textContent = dashboardData.timestamp;

// Função para inicializar o dashboard
function initializeDashboard() {
    // Preencher contadores da visão geral
    updateOverviewMetrics();
    
    // Configurar navegação
    setupNavigation();
}

// Atualizar métricas de visão geral
function updateOverviewMetrics() {
    // Oportunidades
    const opportunities = dashboardData.analysis.opportunities || [];
    document.getElementById('opportunities-count').textContent = opportunities.length;
    
    // ROI médio
    let totalRoi = 0;
    opportunities.forEach(opp => {
        if (opp.roi_percentage) {
            totalRoi += opp.roi_percentage;
        }
    });
    const avgRoi = opportunities.length > 0 ? totalRoi / opportunities.length : 0;
    document.getElementById('avg-roi').textContent = avgRoi.toFixed(2) + '%';
    
    // Tendências
    const trends = dashboardData.analysis.market_trends || [];
    document.getElementById('trends-count').textContent = trends.length;
    
    // Campanhas
    const campaigns = (dashboardData.automation.campaigns || []);
    document.getElementById('campaigns-count').textContent = campaigns.length;
}

// Configurar navegação entre seções
function setupNavigation() {
    const menuItems = document.querySelectorAll('.menu li');
    
    menuItems.forEach(item => {
        item.addEventListener('click', function() {
            // Remover classe active de todos os itens
            menuItems.forEach(i => i.classList.remove('active'));
            
            // Adicionar classe active ao item clicado
            this.classList.add('active');
            
            // Obter seção a ser exibida
            const section = this.getAttribute('data-section');
            
            // Ocultar todas as seções
            document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
            
            // Exibir a seção correspondente
            document.getElementById(`${section}-section`).classList.add('active');
        });
    });
}

// Inicializar o dashboard quando o documento estiver carregado
document.addEventListener('DOMContentLoaded', initializeDashboard);
